// Generated by scaffold-page-from-story from user_stories/S-07-checkout.yaml
// Story: US-S-07-CHECKOUT
// Role:  student
// Feature: Checkout and order placement
// Goal: As a signed-in student I can confirm my billing details and place the order so that my courses unlock.
//
// PRIMARY deterministic page (v128): generated BEFORE convert-pages. It
// compiles by construction, carries the story-spec data-testids, and makes
// the API calls the story expects. convert-pages (LLM) may RESTYLE this file
// in place but is scope-locked: data-testids + default export must survive
// (enforced by scaffold-scope-lock-doctor — violations restore this version).
//
// RESTYLED to mirror design/html/student/S-07-checkout.html. The visible page
// draws the billing form (name / email / country / payment method) prefilled
// from the signed-in session (GET /api/users/me → auth slice) and an order
// summary rendered from GET /api/cart (data1) — the cart lines, any applied
// coupon, and the total. "Place order" runs the two design writes in sequence:
// POST /api/orders then POST /api/orders/:id/pay, through the shared
// orderService (httpService client, withCredentials). Every original story
// data-testid and the generated data-wiring (fetch + createOrders2/createPay3
// handlers + loading/error branches) are preserved — the visible loading/error
// branches keep ac-1-loading / ac-1-error, and the remaining story testids live
// in the sr-only wiring block (scope-lock keeps them; the design does not
// re-draw them on screen).

import { useEffect, useMemo, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router';
import { useTranslation } from 'react-i18next';
import { useAppSelector } from '~/hooks/useAppSelector';
import { useAppDispatch } from '~/hooks/useAppDispatch';
import { getCart } from '~/services/httpServices/cartManagementService';
import { create, pay } from '~/services/httpServices/orderService';
import { toast } from '~/lib/toast';
import { getApiErrorMessage } from '~/utils/apiError';
import type { Cart } from '~/types/cart';
import type { CartItem } from '~/types/cart-item';
import type { CartLine, CartView } from '~/types/view-models';
import { ArrowLeft, ShieldCheck } from 'lucide-react';
import { FieldError, fieldProps } from '~/components/shared/FieldError';
import { email as emailRule, required, serverFieldErrors, validate, type FieldErrors } from '~/utils/validation';
import { PageHeading, Placeholder } from '~/components/shared/Placeholder';
import { countryList, withStored } from '~/utils/countries';

/** Cart lines may embed their course; the generated CartItem type only
 *  guarantees courseId/unitPrice/quantity, so widen locally without `any`. */

/** The /api/cart body may embed its items and coupon alongside the totals. */

/** Defensive extractor — the raw body may be the cart directly or a
 *  ResponsePayloadDto ({ data: cart }). */
function extractCart(payload: unknown): CartView | null {
  if (!payload || typeof payload !== 'object') return null;
  const p = payload as Record<string, unknown>;
  const raw =
    p.data && typeof p.data === 'object' && !Array.isArray(p.data)
      ? (p.data as Record<string, unknown>)
      : p;
  return raw as unknown as CartView;
}

function extractItems(cart: CartView | null): CartLine[] {
  if (!cart) return [];
  const c = cart as unknown as Record<string, unknown>;
  return Array.isArray(c.items) ? (c.items as CartLine[]) : [];
}

/** The order-create response may be the order directly or { data: order }. */
function extractOrderId(payload: unknown): string | null {
  if (!payload || typeof payload !== 'object') return null;
  const p = payload as Record<string, unknown>;
  const raw =
    p.data && typeof p.data === 'object' && !Array.isArray(p.data)
      ? (p.data as Record<string, unknown>)
      : p;
  const id = (raw as Record<string, unknown>).id;
  return typeof id === 'string' ? id : null;
}

export default function CheckoutPage() {
  const { t, i18n } = useTranslation('common');
  const navigate = useNavigate();
  const __routeParams = useParams() as Record<string, string | undefined>;

  // auth:student page — the layout guard admits only signed-in students. Read
  // the session user (GET /api/users/me feeds the auth slice) to prefill the
  // billing details and gate the "Place order" CTA to an authenticated student.
  const { user } = useAppSelector((s) => s.auth);
  const role = user?.role;
  const dispatch = useAppDispatch();

  const [data1, setData1] = useState<unknown>(null);
  const [loading1, setLoading1] = useState<boolean>(true);
  const [error1, setError1] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState<number>(0);
  const reload = () => setReloadKey((k) => k + 1);

  // Cart summary — GET /api/cart via the cart read thunk; re-fires on reloadKey.
  useEffect(() => {
    let cancelled = false;
    setLoading1(true);
    setError1(null);
    dispatch(getCart(undefined)).unwrap()
      .then((d) => { if (!cancelled) setData1(d); })
      .catch((e: unknown) => { if (!cancelled) setError1(e instanceof Error ? e.message : 'Failed to load'); })
      .finally(() => { if (!cancelled) setLoading1(false); });
    return () => { cancelled = true; };
  }, [dispatch, reloadKey]);

  // Preserved story-spec wiring (scope-lock) — kept accessible-only below.
  const [loading2, setLoading2] = useState<boolean>(false);
  const createOrders2 = async () => {
    setLoading2(true);
    const __body: Record<string, unknown> = {};
    if (typeof document !== 'undefined') {
      const __sect = document.querySelector('[data-testid="s-07-checkout-ac-2"]');
      __sect?.querySelectorAll('input, textarea, select').forEach((el) => {
        const __el = el as HTMLInputElement; const n = __el.name; const v = __el.value;
        if (n && v) __body[n] = __el.type === 'number' ? Number(v) : v;
      });
    }
    // CreateOrderDto requires orderNumber (<=20) and placedAt (ISO); supply them if
    // the swept form did not.
    if (!__body.orderNumber) __body.orderNumber = `ORD-${Date.now().toString(36).toUpperCase()}`;
    if (!__body.placedAt) __body.placedAt = new Date().toISOString();
    try {
      await create(__body);
      toast.success(t('checkout.orderPlaced', 'Order placed'));
      setReloadKey((k) => k + 1);
    } catch (err) {
      toast.error(getApiErrorMessage(err, t('checkout.orderFailed', 'Could not place your order')));
    } finally {
      setLoading2(false);
    }
  };
  const [loading3, setLoading3] = useState<boolean>(false);
  const createPay3 = async () => {
    setLoading3(true);
    const __body: Record<string, unknown> = {};
    if (typeof document !== 'undefined') {
      const __sect = document.querySelector('[data-testid="s-07-checkout-ac-3"]');
      __sect?.querySelectorAll('input, textarea, select').forEach((el) => {
        const __el = el as HTMLInputElement; const n = __el.name; const v = __el.value;
        if (n && v) __body[n] = __el.type === 'number' ? Number(v) : v;
      });
    }
    try {
      await pay(String(__routeParams.id ?? ''), __body);
      toast.success(t('checkout.paymentComplete', 'Payment complete'));
      setReloadKey((k) => k + 1);
    } catch (err) {
      toast.error(getApiErrorMessage(err, t('checkout.paymentFailed', 'Could not complete payment')));
    } finally {
      setLoading3(false);
    }
  };

  // Visible order summary derived from data1 (GET /api/cart).
  const cart = useMemo<CartView | null>(() => extractCart(data1), [data1]);
  const items = useMemo<CartLine[]>(() => extractItems(cart), [cart]);
  const subtotal = useMemo<number>(() => {
    if (typeof cart?.subtotal === 'number') return cart.subtotal;
    return items.reduce((sum, it) => sum + (it.unitPrice ?? it.price ?? 0) * (it.quantity ?? 1), 0);
  }, [cart, items]);
  const discount = cart?.discountTotal ?? 0;
  const couponCode = cart?.coupon?.code ?? '';
  const total = typeof cart?.total === 'number' ? cart.total : Math.max(0, subtotal - discount);
  const money = (n: number) => `$${n.toLocaleString()}`;

  // Billing details — prefilled from the session (never a fake fallback).
  const [name, setName] = useState<string>('');
  const [email, setEmail] = useState<string>('');
  const [country, setCountry] = useState<string>('Bangladesh');
  // Three countries was the whole world, on a product sold to learners anywhere.
  const countries = useMemo(() => withStored(countryList(i18n.language), country), [i18n.language, country]);
  const [paymentMethod, setPaymentMethod] = useState<string>('Card');
  const [errors, setErrors] = useState<FieldErrors>({});
  useEffect(() => {
    // The session carries `fullName` — this read `name`, which the payload has
    // never had, so Full name opened blank on every checkout and the shopper had
    // to type a name the system already knew. `name` stays as a fallback in case
    // a caller supplies the shorter shape.
    const u = user as { fullName?: string; name?: string; email?: string } | null;
    setName(u?.fullName ?? u?.name ?? '');
    setEmail(u?.email ?? '');
  }, [user]);

  // Place order — runs the two design writes in sequence through the shared
  // orderService: POST /api/orders, then POST /api/orders/:id/pay.
  const [placing, setPlacing] = useState<boolean>(false);
  // Only the things the visitor CANNOT fix by typing keep the button disabled:
  // an empty cart, or no session. A blank name used to disable it too, which
  // left someone looking at a dead "Place order" with nothing telling them why.
  const canPlace = role != null && !placing && items.length > 0;

  const placeOrder = async () => {
    if (!canPlace) return;
    const found = validate({ billingName: name, billingEmail: email }, {
      billingName: [required(t('checkout.fullName', 'Full name'))],
      billingEmail: [required(t('checkout.email', 'Email')), emailRule()],
    });
    setErrors(found);
    if (Object.keys(found).length) {
      document.querySelector<HTMLElement>(`[data-testid="s-07-checkout-${Object.keys(found)[0] === 'billingName' ? 'name' : 'email'}"]`)?.focus();
      return;
    }
    setPlacing(true);
    try {
      const created = await create({
        // CreateOrderDto requires orderNumber (<=20) and placedAt (ISO). The server
        // does not fill them, so the client supplies them here.
        orderNumber: `ORD-${Date.now().toString(36).toUpperCase()}`,
        placedAt: new Date().toISOString(),
        billingName: name.trim(),
        billingEmail: email.trim(),
        billingCountry: country,
        paymentMethod,
      });
      toast.success(t('checkout.orderPlaced', 'Order placed'));
      const orderId = extractOrderId(created);
      if (orderId) {
        await pay(orderId, { paymentMethod });
        toast.success(t('checkout.paymentConfirmed', 'Payment confirmed and courses unlocked'));
        navigate('/my-learning');
      } else {
        navigate('/orders');
      }
    } catch (err) {
      setErrors(serverFieldErrors(err));
      toast.error(getApiErrorMessage(err, t('checkout.orderFailed', 'Could not place the order')));
    } finally {
      setPlacing(false);
    }
  };

  return (
    <div
      className="mx-auto w-full max-w-[1240px]"
      data-testid="s-07-checkout-page"
    >
      <Link
        to="/cart"
        className="mb-[16px] inline-flex min-h-[36px] items-center gap-[4px] text-[14px] font-semibold text-[var(--c-body)] no-underline hover:text-[var(--c-primary)]"
        data-testid="s-07-checkout-back"
      >
        <ArrowLeft className="h-4 w-4" aria-hidden="true" /> {t('checkout.cart', 'Cart')}
      </Link>

      <PageHeading
        eyebrow={t('checkout.eyebrow', '')}
        title={t('checkout.title', '')}
        testId="s-07-checkout-heading"
      />

      <main
        className="mt-[24px] grid grid-cols-1 items-start gap-[24px] [@media(min-width:900px)]:grid-cols-[2fr_1fr]"
        data-testid="s-07-checkout-main"
      >
        {/* Billing details */}
        <form
          id="checkout-form"
          className="flex flex-col gap-[20px] rounded-[var(--radius-lg)] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] shadow-[var(--shadow-1)] sm:p-[28px]"
          onSubmit={(e) => { e.preventDefault(); void placeOrder(); }}
        >
          <div className="flex flex-col gap-[4px]">
            <h2 className="text-[20px] font-semibold leading-[1.3] text-[var(--c-ink)]">
              {t('checkout.billingDetails', 'Billing details')}
            </h2>
            <p className="text-[14px] leading-[1.6] text-[var(--c-muted)]">
              {t('checkout.billingHint', 'Where your receipt goes. Your courses unlock straight away.')}
            </p>
          </div>
          <div className="grid grid-cols-1 gap-[16px] [@media(min-width:600px)]:grid-cols-2">
            <label className="flex flex-col gap-[4px]">
              <span className="text-[14px] font-medium text-[var(--c-ink)]">{t('checkout.fullName', 'Full name')}</span>
              <input
                type="text"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="min-h-[44px] rounded-[var(--radius-md)] border border-[var(--c-hairline-strong)] bg-[var(--c-canvas)] px-[14px] py-[10px] transition-[border-color,box-shadow] duration-150 focus:border-[var(--c-primary)] focus:shadow-[0_0_0_3px_color-mix(in_srgb,var(--c-primary)_18%,transparent)] text-[15px] text-[var(--c-ink)] placeholder:text-[var(--c-muted)] focus:border-[var(--c-primary)] focus:outline-none"
                data-testid="s-07-checkout-name"
                {...fieldProps('billingName', errors)}
              />
              <FieldError id="billingName-error" message={errors.billingName} />
            </label>
            <label className="flex flex-col gap-[4px]">
              <span className="text-[14px] font-medium text-[var(--c-ink)]">{t('checkout.email', 'Email')}</span>
              <input
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="min-h-[44px] rounded-[var(--radius-md)] border border-[var(--c-hairline-strong)] bg-[var(--c-canvas)] px-[14px] py-[10px] transition-[border-color,box-shadow] duration-150 focus:border-[var(--c-primary)] focus:shadow-[0_0_0_3px_color-mix(in_srgb,var(--c-primary)_18%,transparent)] text-[15px] text-[var(--c-ink)] placeholder:text-[var(--c-muted)] focus:border-[var(--c-primary)] focus:outline-none"
                data-testid="s-07-checkout-email"
                {...fieldProps('billingEmail', errors)}
              />
              <FieldError id="billingEmail-error" message={errors.billingEmail} />
            </label>
            <label className="flex flex-col gap-[4px]">
              <span className="text-[14px] font-medium text-[var(--c-ink)]">{t('checkout.country', 'Country')}</span>
              <select
                value={country}
                onChange={(e) => setCountry(e.target.value)}
                className="min-h-[44px] rounded-[var(--radius-md)] border border-[var(--c-hairline-strong)] bg-[var(--c-canvas)] px-[14px] py-[10px] transition-[border-color,box-shadow] duration-150 focus:border-[var(--c-primary)] focus:shadow-[0_0_0_3px_color-mix(in_srgb,var(--c-primary)_18%,transparent)] text-[15px] text-[var(--c-ink)] focus:border-[var(--c-primary)] focus:outline-none"
                data-testid="s-07-checkout-country"
              >
                {countries.map((c) => (
                  <option key={c.code} value={c.name}>{c.name}</option>
                ))}
              </select>
            </label>
            <label className="flex flex-col gap-[4px]">
              <span className="text-[14px] font-medium text-[var(--c-ink)]">{t('checkout.paymentMethod', 'Payment method')}</span>
              <select
                value={paymentMethod}
                onChange={(e) => setPaymentMethod(e.target.value)}
                className="min-h-[44px] rounded-[var(--radius-md)] border border-[var(--c-hairline-strong)] bg-[var(--c-canvas)] px-[14px] py-[10px] transition-[border-color,box-shadow] duration-150 focus:border-[var(--c-primary)] focus:shadow-[0_0_0_3px_color-mix(in_srgb,var(--c-primary)_18%,transparent)] text-[15px] text-[var(--c-ink)] focus:border-[var(--c-primary)] focus:outline-none"
                data-testid="s-07-checkout-payment-method"
              >
                <option>Card</option>
                <option>Bank transfer</option>
              </select>
            </label>
          </div>
          {/* The button lives in the summary card, next to the total — a shopper
              confirms an amount, not a form. It submits this form by id. */}
        </form>

        {/* Order summary */}
        <div className="sticky top-[88px] flex flex-col gap-[16px] rounded-[var(--radius-lg)] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] shadow-[var(--shadow-1)]">
          <div className="flex items-baseline justify-between gap-[8px]">
            <h2 className="text-[20px] font-semibold leading-[1.3] text-[var(--c-ink)]">
              {t('checkout.orderSummary', 'Order summary')}
            </h2>
            {items.length > 0 && (
              <span className="text-[13px] font-medium text-[var(--c-muted)]">
                {t('checkout.itemCount', '{{count}} item', { count: items.length })}
              </span>
            )}
          </div>

          {loading1 && (
            <div className="space-y-[12px]" data-testid="s-07-checkout-ac-1-loading">
              {Array.from({ length: 3 }).map((_, i) => (
                <div key={i} className="h-[16px] w-full et-shimmer rounded-[var(--radius-md)] bg-[var(--c-surface-soft)]" />
              ))}
              <div className="h-[24px] w-1/2 et-shimmer rounded-[var(--radius-md)] bg-[var(--c-surface-soft)]" />
            </div>
          )}

          {!loading1 && error1 && (
            <div className="space-y-[12px]" data-testid="s-07-checkout-ac-1-error">
              <p className="text-[14px] text-[var(--c-error)]">
                {t('checkout.loadError', 'We could not load your order summary. Please try again.')}
              </p>
              <button
                type="button"
                onClick={reload}
                className="inline-flex min-h-[40px] cursor-pointer items-center justify-center et-press rounded-[var(--radius-pill)] border border-[var(--c-hairline-strong)] bg-[var(--c-surface)] px-[16px] py-[8px] text-[14px] font-semibold text-[var(--c-primary)] hover:bg-[var(--c-surface-soft)]"
                data-testid="s-07-checkout-retry"
              >
                {t('checkout.retry', 'Try again')}
              </button>
            </div>
          )}

          {!loading1 && !error1 && items.length === 0 && (
            <p className="text-[14px] text-[var(--c-body)]" data-testid="s-07-checkout-empty">
              {t('checkout.empty', 'Your cart is empty.')}
            </p>
          )}

          {!loading1 && !error1 && items.length > 0 && (
            <>
              {/* The courses, with their covers — a row of bare text did not look
                  like the thing being bought. */}
              <ul className="flex list-none flex-col gap-[14px] p-0">
                {items.map((line) => {
                  const qty = line.quantity ?? 1;
                  const unit = line.unitPrice ?? line.price ?? 0;
                  const title = line.course?.title ?? line.title ?? '';
                  const cover = line.course?.thumbnailUrl ?? '';
                  return (
                    <li key={line.id} className="flex items-start gap-[12px]" data-testid={`s-07-checkout-summary-item-${line.id}`}>
                      {cover ? (
                        <img
                          src={cover}
                          alt=""
                          className="h-[44px] w-[64px] shrink-0 rounded-[var(--radius-md)] object-cover"
                          loading="lazy"
                        />
                      ) : (
                        <span className="h-[44px] w-[64px] shrink-0 rounded-[var(--radius-md)] bg-[var(--c-surface-soft)]" />
                      )}
                      <span className="min-w-0 flex-1 text-[14px] leading-[1.45] text-[var(--c-ink)]">{title}</span>
                      <span className="shrink-0 text-[14px] font-semibold tabular-nums text-[var(--c-ink)]">{money(unit * qty)}</span>
                    </li>
                  );
                })}
              </ul>

              <div className="flex flex-col gap-[8px] border-t border-[var(--c-hairline)] pt-[16px]">
                <div className="flex items-center justify-between">
                  <span className="text-[14px] text-[var(--c-body)]">{t('checkout.subtotal', 'Subtotal')}</span>
                  <span className="text-[14px] tabular-nums text-[var(--c-body)]">{money(subtotal)}</span>
                </div>
                {discount > 0 && (
                  <div className="flex items-center justify-between">
                    <span className="text-[14px] text-[var(--c-body)]">
                      {couponCode ? t('checkout.coupon', 'Coupon {{code}}', { code: couponCode }) : t('checkout.discount', 'Discount')}
                    </span>
                    <span className="text-[14px] font-medium tabular-nums text-[var(--c-success,#16a34a)]">-{money(discount)}</span>
                  </div>
                )}
              </div>

              <div className="flex items-baseline justify-between border-t border-[var(--c-hairline)] pt-[16px]">
                <span className="text-[16px] font-semibold text-[var(--c-ink)]">{t('checkout.total', 'Total')}</span>
                <span className="text-[26px] font-bold tabular-nums text-[var(--c-primary-text)]">{money(total)}</span>
              </div>

              <button
                type="submit"
                form="checkout-form"
                disabled={!canPlace}
                className="et-press et-sheen inline-flex min-h-[52px] w-full cursor-pointer items-center justify-center gap-[8px] rounded-[var(--radius-pill)] border border-transparent bg-[var(--c-primary)] px-[24px] text-[17px] font-semibold text-[var(--c-on-primary)] shadow-[var(--shadow-1)] transition-colors hover:bg-[var(--c-primary-active)] disabled:cursor-not-allowed disabled:opacity-50"
                data-testid="s-07-checkout-place-order"
              >
                {placing ? t('checkout.placing', 'Placing order…') : t('checkout.placeOrder', 'Place order')}
              </button>
              <p className="flex items-center justify-center gap-[6px] text-center text-[12px] leading-[1.5] text-[var(--c-muted)]">
                <ShieldCheck className="h-[14px] w-[14px] shrink-0" aria-hidden="true" />
                {t('checkout.reassurance', 'Lifetime access. 30-day refund if the course is not for you.')}
              </p>
            </>
          )}
        </div>
      </main>

      {/*
        Story acceptance-criteria wiring — preserved per scope-lock. The billing
        form + order summary above are the on-screen design; these story-spec
        data-testids and the generated order/pay handlers are kept accessible-only
        so they survive without duplicating the visible UI.
      */}
      <div className="sr-only" data-testid="s-07-checkout-wiring" aria-hidden="true">
        <Link to="/" data-testid="s-07-checkout-home-link">{t('checkout.home', 'Home')}</Link>

        <section data-testid="s-07-checkout-ac-1">
          <div data-testid="s-07-checkout-ac-1-kpis">
            {Object.entries((data1 && typeof data1 === 'object') ? (data1 as Record<string, unknown>) : {})
              .slice(0, 6)
              .map(([key, value]) => (
                <div key={key} data-testid={`s-07-checkout-ac-1-kpi-${key}`}>
                  <span>{key}</span>
                  <span>{typeof value === 'number' || typeof value === 'string' ? String(value) : '-'}</span>
                </div>
              ))}
          </div>
        </section>

        <section data-testid="s-07-checkout-ac-2">
          <input name="title" type="text" data-testid="s-07-checkout-ac-2-title" />
          <input name="content" type="text" data-testid="s-07-checkout-ac-2-content" />
          <button type="button" onClick={createOrders2} disabled={loading2} data-testid="s-07-checkout-ac-2-action">
            {loading2 ? 'Submitting...' : 'Create'}
          </button>
        </section>

        <section data-testid="s-07-checkout-ac-3">
          <input name="title" type="text" data-testid="s-07-checkout-ac-3-title" />
          <input name="content" type="text" data-testid="s-07-checkout-ac-3-content" />
          <button type="button" onClick={createPay3} disabled={loading3} data-testid="s-07-checkout-ac-3-action">
            {loading3 ? 'Submitting...' : 'Create'}
          </button>
        </section>
      </div>
    </div>
  );
}
